    output reg [1:0] light,
    output reg walk
);

reg [2:0] state;
reg [2:0] next_state;
reg [3:0] count;

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        count <= 4'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            next_state <= 3'd0;
            count <= 4'd3;
        end else if (state == 3'd1) begin
            next_state <= 3'd1;
            count <= 4'd4;
        end else if (state == 3'd2) begin
            next_state <= 3'd2;
            count <= 4'd2;
        end else if (state == 3'd3) begin
            next_state <= 3'd0;
            count <= 4'd3;
        end else if (state == 3'd4) begin
            next_state <= 3'd0;
            count <= 4'd3;
        end else if (state == 3'd5) begin
            next_state <= 3'd1;
            count <= 4'd4;
        end else if (state == 3'd6) begin
            next_state <= 3'd2;
            count <= 4'd2;
        end else if (state == 3'd7) begin
            next_state <= 3'd0;
            count <= 4'd3;
        end

        if (count > 1) begin
            count <= count - 1;
        end else begin
            count <= 4'd0;
            state <= next_state;
        end

        if (state == 3'd0) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else if (state == 3'd1) begin
            light <= 2'b01;
            walk <= 1'b0;
        end else if (state == 3'd2) begin
            light <= 2'b10;
            walk <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (state == 3'd1 && ped) begin
            light <= 2'b10;
            walk <= 1'b0;
        end
    end
end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [2:0] state;
reg [2:0] next_state;
reg [3:0] cycle_count;

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        cycle_count <= 4'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        if (ped && light == 2'b01) begin
            next_state <= 3'd2;
            cycle_count <= 4'd0;
        end else begin
            next_state <= state;
        end

        if (state == 3'd0) begin
            if (cycle_count < 3) begin
                next_state <= 3'd0;
                cycle_count <= cycle_count + 1;
            end else begin
                next_state <= 3'd1;
                cycle_count <= 4'd0;
            end
        end else if (state == 3'd1) begin
            if (cycle_count < 4) begin
                next_state <= 3'd1;
                cycle_count <= cycle_count + 1;
            end else begin
                next_state <= 3'd2;
                cycle_count <= 4'd0;
            end
        end else if (state == 3'd2) begin
            if (cycle_count < 2) begin
                next_state <= 3'd2;
                cycle_count <= cycle_count + 1;
            end else begin
                next_state <= 3'd0;
                cycle_count <= 4'd0;
            end
        end

        state <= next_state;
        cycle_count <= (state == 3'd2) ? cycle_count + 1 : cycle_count;

        case (state)
            3'd0: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
            3'd1: begin
                light <= 2'b01;
                walk <= 1'b0;
            end
            3'd2: begin
                light <= 2'b10;
                walk <= 1'b0;
            end
        endcase
    end
end

endmodule

